mapper.select:
select p.* from life_post p where p.deleted = 0 and p.status = 1
and p.user_id = #{query.userId}
and p.user_id in ( select f.follow_user_id from life_follow f where f.user_id = #{query.currentUserId} and f.deleted = 0 )
and p.category = #{query.category}
and (p.title like concat('%', #{query.keyword}, '%') or p.content like concat('%', #{query.keyword}, '%'))
order by p.create_time desc, p.id desc
